import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { KeyRound, Lock, ShieldCheck, ArrowRight, Smartphone, CheckCircle2, ChevronLeft } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { authAPI } from '../services/api';
import { pushBackHandler } from '../utils/backHandler';
import './Auth.css';

const ActivateAccount = () => {
  const [step, setStep] = useState(1); // 1: Code, 2: New Password, 3: Success
  const [formData, setFormData] = useState({
    numeroTelephone: '',
    code: '',
    nouveauMotDePasse: '',
    confirmPassword: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    const off = pushBackHandler(() => {
      if (step === 3) { navigate('/auth'); return true; }
      if (step > 1) { setStep(s => s - 1); setError(''); return true; }
      return false;
    });
    return off;
  }, [step, navigate]);

  const handleNextStep = (e) => {
    e.preventDefault();
    if (step === 1 && formData.code.length === 8) {
      setStep(2);
    } else if (step === 2) {
      if (formData.nouveauMotDePasse !== formData.confirmPassword) {
        setError("Les mots de passe ne correspondent pas.");
        return;
      }
      handleActivation();
    }
  };

  const handleBack = () => {
    if (step === 3) {
      navigate('/auth');
      return;
    }
    if (step > 1) {
      setStep((s) => s - 1);
      setError('');
      return;
    }
    navigate('/auth');
  };

  const handleActivation = async () => {
    setLoading(true);
    setError('');
    try {
      await authAPI.activateAccount({
        numeroTelephone: formData.numeroTelephone,
        code: formData.code,
        nouveauMotDePasse: formData.nouveauMotDePasse
      });
      setStep(3);
    } catch (err) {
      setError("Code invalide ou erreur serveur. Veuillez vérifier vos informations.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-container">
      <div className="bg-bubbles">
        {[...Array(5)].map((_, i) => (
          <div key={i} className={`bubble bubble-${i}`}></div>
        ))}
      </div>

      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="auth-card-wrapper"
        style={{ maxWidth: '500px' }}
      >
        <button
          type="button"
          onClick={handleBack}
          style={{
            display: 'inline-flex', alignItems: 'center', gap: '6px',
            marginBottom: '1rem', padding: '8px 14px', borderRadius: '10px',
            border: '1px solid rgba(255,255,255,0.15)', background: 'transparent',
            color: '#475569', cursor: 'pointer', fontWeight: 600, fontSize: '0.85rem',
          }}
        >
          <ChevronLeft size={16} />
          {step > 1 && step < 3 ? 'Étape précédente' : 'Retour à la connexion'}
        </button>
        <div className="auth-card" style={{ border: '2px solid var(--secondary)' }}>
          <div className="auth-header" style={{ textAlign: 'center' }}>
            <div style={{ background: 'var(--secondary)', width: '60px', height: '60px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyCenter: 'center', margin: '0 auto 1.5rem', color: 'var(--primary)' }}>
              {step === 3 ? <CheckCircle2 size={30} /> : <ShieldCheck size={30} />}
            </div>
            <h2>{step === 3 ? "Compte Activé !" : "Activation Sécurisée"}</h2>
            <p>
              {step === 1 && "Entrez le code secret reçu par votre supérieur."}
              {step === 2 && "Définissez maintenant votre mot de passe personnel."}
              {step === 3 && "Votre accès est désormais opérationnel."}
            </p>
          </div>

          {step < 3 ? (
            <form onSubmit={handleNextStep} className="auth-form">
              {error && <p style={{ color: 'var(--danger)', fontSize: '0.85rem', textAlign: 'center', background: 'rgba(225, 29, 72, 0.1)', padding: '10px', borderRadius: '10px' }}>{error}</p>}
              
              {step === 1 && (
                <>
                  <div className="input-group">
                    <label><Smartphone size={16} /> Votre Numéro WhatsApp</label>
                    <input 
                      type="tel" 
                      placeholder="+228..." 
                      required 
                      value={formData.numeroTelephone}
                      onChange={(e) => setFormData({...formData, numeroTelephone: e.target.value})}
                    />
                  </div>
                  <div className="input-group">
                    <label><KeyRound size={16} /> Code de modification (8 caractères)</label>
                    <input 
                      type="text" 
                      placeholder="EX: A1B2C3D4" 
                      maxLength="8"
                      required 
                      style={{ letterSpacing: '3px', fontWeight: '900', textTransform: 'uppercase' }}
                      value={formData.code}
                      onChange={(e) => setFormData({...formData, code: e.target.value.toUpperCase()})}
                    />
                  </div>
                </>
              )}

              {step === 2 && (
                <>
                  <div className="input-group">
                    <label><Lock size={16} /> Nouveau mot de passe</label>
                    <input 
                      type="password" 
                      placeholder="••••••••" 
                      required 
                      value={formData.nouveauMotDePasse}
                      onChange={(e) => setFormData({...formData, nouveauMotDePasse: e.target.value})}
                    />
                  </div>
                  <div className="input-group">
                    <label><Lock size={16} /> Confirmer le mot de passe</label>
                    <input 
                      type="password" 
                      placeholder="••••••••" 
                      required 
                      value={formData.confirmPassword}
                      onChange={(e) => setFormData({...formData, confirmPassword: e.target.value})}
                    />
                  </div>
                </>
              )}

              <button type="submit" className="btn-auth" disabled={loading}>
                {loading ? "Traitement..." : step === 1 ? "Vérifier le code" : "Activer mon compte"}
                <ArrowRight size={20} />
              </button>
            </form>
          ) : (
            <div style={{ textAlign: 'center', marginTop: '2rem' }}>
              <p style={{ color: '#334155', marginBottom: '2rem' }}>Félicitations ! Vous pouvez maintenant vous connecter avec vos nouveaux identifiants.</p>
              <button onClick={() => navigate('/auth')} className="btn-auth" style={{ width: '100%' }}>
                Aller à la connexion
              </button>
            </div>
          )}
        </div>
      </motion.div>
    </div>
  );
};

export default ActivateAccount;

