import React, { useState, useEffect } from 'react';
import { Search, Globe } from 'lucide-react';
import '../styles/CountrySelector.css';

const CountrySelector = ({ selectedCountry, onCountrySelect }) => {
  const [countries, setCountries] = useState([]);
  const [isOpen, setIsOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [filteredCountries, setFilteredCountries] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Load countries from backend
  useEffect(() => {
    const loadCountries = async () => {
      try {
        setLoading(true);
        const apiBase = process.env.REACT_APP_API_URL || 'http://localhost:8080/api';
        const response = await fetch(`${apiBase}/countries/africa`);
        if (!response.ok) throw new Error('Impossible de charger les pays');
        const data = await response.json();
        setCountries(data);
        setFilteredCountries(data);
      } catch (err) {
        console.error('Error loading countries:', err);
        setError('Erreur: impossible de charger les pays');
      } finally {
        setLoading(false);
      }
    };

    loadCountries();
  }, []);

  // Handle search
  useEffect(() => {
    if (!searchQuery.trim()) {
      setFilteredCountries(countries);
    } else {
      const query = searchQuery.toLowerCase();
      const filtered = countries.filter(c =>
        c.name.toLowerCase().includes(query) ||
        c.code.toLowerCase().includes(query) ||
        c.phoneCode.includes(query)
      );
      setFilteredCountries(filtered);
    }
  }, [searchQuery, countries]);

  const handleSelectCountry = (country) => {
    onCountrySelect(country);
    setIsOpen(false);
    setSearchQuery('');
  };

  if (loading) {
    return <div className="country-selector loading">Chargement des pays...</div>;
  }

  if (error) {
    return <div className="country-selector error">{error}</div>;
  }

  return (
    <div className="country-selector-wrapper">
      <div className="country-selector-header">
        <Globe size={18} className="header-icon" />
        <label>Pays (54 pays africains disponibles)</label>
      </div>

      {!selectedCountry ? (
        <div className="country-selector-dropdown">
          <div className="search-box">
            <Search size={18} className="search-icon" />
            <input
              type="text"
              placeholder="Rechercher un pays... (ex: Togo, TG, +228)"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              onFocus={() => setIsOpen(true)}
              className="search-input"
            />
          </div>

          {isOpen && (
            <div className="countries-list">
              {filteredCountries.length > 0 ? (
                filteredCountries.map((country) => (
                  <button
                    key={country.code}
                    type="button"
                    className="country-option"
                    onClick={() => handleSelectCountry(country)}
                  >
                    <span className="country-flag">{country.emoji}</span>
                    <span className="country-info">
                      <span className="country-name">{country.name}</span>
                      <span className="country-code">({country.code}) {country.phoneCode}</span>
                    </span>
                  </button>
                ))
              ) : (
                <div className="no-countries">Aucun pays trouvé</div>
              )}
            </div>
          )}

          {isOpen && (
            <div
              className="dropdown-backdrop"
              onClick={() => setIsOpen(false)}
            />
          )}
        </div>
      ) : (
        <div className="selected-country">
          <div className="country-display">
            <span className="country-flag">{selectedCountry.emoji}</span>
            <div className="country-details">
              <span className="selected-name">{selectedCountry.name}</span>
              <span className="phone-info">{selectedCountry.phoneCode} • {selectedCountry.phoneLength} chiffres</span>
            </div>
          </div>
          <button
            type="button"
            className="change-country-btn"
            onClick={() => {
              onCountrySelect(null);
              setSearchQuery('');
            }}
          >
            Changer
          </button>
        </div>
      )}
    </div>
  );
};

export default CountrySelector;
