import axios from 'axios';
import { clearSession } from '../utils/authSession';

const API_BASE = process.env.REACT_APP_API_URL || 'http://localhost:8080/api';

const getStoredUserId = () => {
  try {
    const u = JSON.parse(localStorage.getItem('user') || '{}');
    return u.id || localStorage.getItem('userId') || '';
  } catch {
    return localStorage.getItem('userId') || '';
  }
};

// URL racine du backend (sans /api) — pour accéder aux fichiers uploadés
export const BACKEND_BASE_URL = API_BASE.replace(/\/api$/, '');

const api = axios.create({
  baseURL: API_BASE,
  headers: {
    'Content-Type': 'application/json'
  },
  timeout: 60000,
});

// ✅ Instance SANS auth — pour les endpoints publics (/public/stats, keep-alive, etc.)
// Évite d'envoyer un token JWT expiré sur les routes publiques → plus de 401 parasite.
const publicApi = axios.create({
  baseURL: API_BASE,
  timeout: 45000,
});

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const isRetriableError = (error) => {
  const status = error?.response?.status;
  const code = error?.code;
  const msg = String(error?.message || '').toLowerCase();
  if (!status) {
    return (
      code === 'ECONNABORTED' ||
      code === 'ERR_NETWORK' ||
      msg.includes('network error') ||
      msg.includes('timeout')
    );
  }
  return status === 502 || status === 503 || status === 504 || status === 408 || status === 429;
};

/** Réveille le backend Render (cold start ~30–90 s) avant les chargements critiques.
 *  Utilise publicApi (sans JWT) pour éviter les 401 sur token expiré. */
export const wakeBackend = async (onProgress) => {
  const maxAttempts = 8;
  for (let i = 0; i < maxAttempts; i += 1) {
    onProgress?.(i + 1, maxAttempts);
    try {
      await publicApi.get('/public/stats');
      return true;
    } catch {
      if (i < maxAttempts - 1) {
        await sleep(4000 + i * 2000);
      }
    }
  }
  return false;
};

export const getApiErrorMessage = (error, fallback = 'Impossible de charger les données.') => {
  const status = error?.response?.status;
  const code = error?.code;
  const msg = String(error?.message || '').toLowerCase();
  if (status === 401) return 'Session expirée. Reconnectez-vous.';
  if (status === 403) return 'Accès refusé pour ce compte.';
  if (status === 404) return 'Ressource introuvable sur le serveur.';
  if (status === 502 || status === 503 || status === 504) {
    return 'Le serveur démarre ou est indisponible. Réessayez dans quelques instants.';
  }
  if (code === 'ECONNABORTED' || msg.includes('timeout')) {
    return 'Délai dépassé — connexion lente ou serveur en veille. Réessayez.';
  }
  if (code === 'ERR_NETWORK' || msg.includes('network error')) {
    return 'Pas de connexion Internet ou serveur injoignable.';
  }
  return error?.response?.data?.error || fallback;
};

// Intercepteur pour ajouter automatiquement le token JWT
// + supprimer Content-Type pour FormData (Axios v1.x + Capacitor Android)
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }

  // ✅ Fix Axios v1.x + Android WebView :
  // Si data est un FormData, supprimer le Content-Type défini par défaut.
  // Le browser/XHR posera automatiquement "multipart/form-data; boundary=..."
  // Sinon le boundary est manquant → le serveur Spring Boot ne peut PAS parser le multipart.
  if (config.data instanceof FormData) {
    config.headers.delete('Content-Type');
  }

  return config;
});

// Retry automatique si le serveur Render est en cold start ou réseau instable
api.interceptors.response.use(
  (response) => response,
  async (error) => {
    const config = error.config || {};
    const retries = config.__retryCount || 0;
    const maxRetries = 5;

    // ✅ Ne JAMAIS retenter les routes IA : l'appel Gemini peut prendre 30s+,
    // 5 retries × 30s = 2,5 minutes → timeout mobile inévitable.
    // AILabController retourne toujours 200 maintenant, donc les retries IA = jamais utiles.
    const isAIRoute = String(config.url || '').includes('/ai/');

    if (!config.__skipRetry && !isAIRoute && isRetriableError(error) && retries < maxRetries) {
      config.__retryCount = retries + 1;
      await sleep(Math.min(2500 * config.__retryCount, 8000));
      return api(config);
    }

    const status = error.response?.status;
    if (status === 401) {
      const url = String(error.config?.url || '');

      // ✅ Routes qui peuvent retourner 401 sans que cela signifie une session expirée
      // (IA, paiements, uploads de fichiers, cours personnels, fichiers partagés, messaging, devoirs)
      const isSafeRoute =
        url.includes('/ai/lab') ||
        url.includes('/ai/') ||
        url.includes('/paiements/') ||
        url.includes('/cours/personnel') ||
        url.includes('/cours/bibliotheque') ||
        url.includes('/cours/mes-cours') ||
        url.includes('/fichiers') ||
        url.includes('/fichiers-partages') ||
        url.includes('/messaging/') ||
        url.includes('/travaux/') ||
        url.includes('/documents/') ||
        url.includes('/soumissions/') ||
        url.includes('/espaces-travail') ||
        url.includes('/taches/') ||
        url.includes('/quiz-challenges') ||
        url.includes('/coursework/') ||
        url.includes('/parent/');

      if (!isSafeRoute) {
        // Vérifier si le message backend confirme vraiment une session expirée
        const backendMsg = String(
          error.response?.data?.error ||
          error.response?.data?.message ||
          ''
        ).toLowerCase();
        const isRealExpiry =
          backendMsg.includes('expir') ||
          backendMsg.includes('token') ||
          backendMsg.includes('connect') ||
          backendMsg === '' || // 401 vide = Spring Security = token invalide
          backendMsg.includes('jwt') ||
          backendMsg.includes('unauthorized');

        if (isRealExpiry) {
          clearSession();
          if (window.location.pathname !== '/auth') {
            // Délai court pour laisser le try/catch du composant appelant se résoudre proprement
            setTimeout(() => {
              if (window.location.pathname !== '/auth') {
                window.location.href = '/auth';
              }
            }, 200);
          }
        }
      }
    }
    return Promise.reject(error);
  }
);

