// Priorité : backend Spring (/api/ai/lab) → fallback service Python direct
const AI_SERVICE_URL = process.env.REACT_APP_AI_SERVICE_URL || 'http://localhost:8001/api/v1';
const AI_LAB_TIMEOUT = 120000;

const aiClient = axios.create({
  baseURL: AI_SERVICE_URL,
  timeout: AI_LAB_TIMEOUT,
});

// ✅ Même fix que pour `api` : supprimer Content-Type pour FormData
aiClient.interceptors.request.use((config) => {
  if (config.data instanceof FormData) {
    config.headers.delete('Content-Type');
  }
  return config;
});

const postAILab = async (path, formData) => {
  const token = localStorage.getItem('token');
  const headers = token ? { Authorization: `Bearer ${token}` } : {};

  // Capacitor WebView expose toujours 'localhost' — ne pas traiter comme dev local
  const isNativeApp = !!(window.Capacitor?.isNativePlatform?.() || window.Capacitor?.platform);
  const isLocalDev = !isNativeApp &&
                     (window.location.hostname === 'localhost' ||
                      window.location.hostname === '127.0.0.1');

  // ══════════════════════════════════════════════════════════════════
  //  ROUTAGE IA — Architecture finale
  //
  //  App native (APK / iOS) : TOUJOURS → service Python directement
  //    aiClient.baseURL = https://revisia-ia.onrender.com/api/v1 (build.yml)
  //    → Python gère texte + fichiers via Gemini multimodal (23 clés en rotation)
  //    → Fallback Java uniquement si Python est totalement indisponible
  //
  //  Dev local : fichier → Python localhost:8001 directement
  //              texte seul → Java localhost:8080 → Python localhost:8001 → Gemini
  // ══════════════════════════════════════════════════════════════════

  if (isNativeApp) {
    // Mobile : chemin direct → Python service (revisia-ia.onrender.com)
    try {
      return await aiClient.post(`/ai${path}`, formData, { timeout: AI_LAB_TIMEOUT });
    } catch (pyErr) {
      console.warn('[AI] Service Python indisponible sur mobile, repli Java:', pyErr?.message);
      // Python DOWN → Java backend comme ultime fallback
      return await api.post(`/ai/lab${path}`, formData, {
        timeout: AI_LAB_TIMEOUT,
        headers,
        __skipRetry: true,
      });
    }
  }

  // Dev local avec fichier : Python localhost direct
  const hasBinaryFile = isLocalDev &&
                        formData instanceof FormData &&
                        typeof formData.has === 'function' &&
                        formData.has('file');

  if (hasBinaryFile) {
    try {
      return await aiClient.post(`/ai${path}`, formData, { timeout: AI_LAB_TIMEOUT });
    } catch (pyErr) {
      console.warn('[AI] Service Python local indisponible, repli Java:', pyErr?.message);
    }
  }

  // Dev local texte seul : Java backend
  try {
    return await api.post(`/ai/lab${path}`, formData, {
      timeout: AI_LAB_TIMEOUT,
      headers,
      __skipRetry: true,
    });
  } catch (backendErr) {
    if (isLocalDev && !hasBinaryFile) {
      try {
        return await aiClient.post(`/ai${path}`, formData, { timeout: AI_LAB_TIMEOUT });
      } catch {
        throw backendErr;
      }
    }
    throw backendErr;
  }
};

const buildAskFormData = (question, contexte = 'Étudiant', file = null, fileUrl = null) => {
  const fd = new FormData();
  fd.append('question', question || '');
  fd.append('contexte_profil', typeof contexte === 'string' ? contexte : 'Étudiant');
  if (file instanceof File || file instanceof Blob) fd.append('file', file);
  else if (fileUrl) fd.append('file_url', fileUrl);
  return fd;
};

export const aiAPI = {
    ask: (question, contexte = 'Étudiant', file = null, fileUrl = null) =>
      postAILab('/chat', buildAskFormData(question, contexte, file, fileUrl)),

    resumerCours: (titreCours, matiereNom, fileUrl) => {
      const fd = new FormData();
      fd.append('titre_cours', titreCours || 'Cours');
      if (matiereNom) fd.append('matiere_nom', matiereNom);
      if (fileUrl) fd.append('file_url', fileUrl);
      return postAILab('/summarize-course', fd);
    },

    genererQuiz: (matiere, niveau, fileUrl) => {
      const fd = new FormData();
      fd.append('sujet', matiere || 'Révision générale');
      fd.append('niveau', niveau || 'L2');
      if (fileUrl) fd.append('file_url', fileUrl);
      return postAILab('/generate-quiz', fd);
    },

    corrigerExamen: ({ nomFichier, titreCours, matiereNom, file } = {}) => {
      const fd = new FormData();
      fd.append('nom_fichier', nomFichier || 'examen');
      if (titreCours) fd.append('titre_cours', titreCours);
      if (matiereNom) fd.append('matiere_nom', matiereNom);
      if (file instanceof File || file instanceof Blob) fd.append('file', file);
      return postAILab('/correct-exam', fd);
    },

    genererCorrection: (titreEpreuve, contenuCours, fileUrl) => {
      const fd = new FormData();
      fd.append('titre_epreuve', titreEpreuve || 'Épreuve');
      if (contenuCours) fd.append('contenu_cours', contenuCours);
      if (fileUrl) fd.append('file_url', fileUrl);
      return postAILab('/generate-correction', fd);
    },

    chat:               (formData) => postAILab('/chat', formData),
    analyzeDocument:    (formData) => postAILab('/analyze-document', formData),
    generateQuiz:       (formData) => postAILab('/generate-quiz', formData),
    summarizeCourse:    (formData) => postAILab('/summarize-course', formData),
    generateCorrection: (formData) => postAILab('/generate-correction', formData),
    correctExam:        (formData) => postAILab('/correct-exam', formData),

    // ─── MODÉRATION & STATUS ──────────────────────────────────────
    // ✅ Routé via backend Render (pas aiClient localhost:8001, inaccessible sur Android)
    moderate: (text) => api.post('/ai/moderate', { text }).catch(() => ({ data: { is_appropriate: true } })),
    getStatus: () => api.get('/ai/health').catch(() => ({ data: { status: 'ok' } })),

    // ─── TUTEUR IA INTELLIGENT (AISmartService) ──────────────────────
    // Sans spam de salutations, réponses claires et réalistes
    askQuestion: (data) => api.post('/ai/question', {
      question: data.question,
      contexte: data.contexte || null
    }),

    explainConcept: (data) => api.post('/ai/explain', {
      concept: data.concept,
      difficulty: data.difficulty || 'NORMAL'
    }),

    analyzeResponse: (data) => api.post('/ai/analyze', {
      subject: data.subject,
      studentAnswer: data.studentAnswer,
      officialAnswer: data.officialAnswer || null
    }),

    generateQuizSmart: (data) => api.post('/ai/quiz', {
      concept: data.concept,
      difficulty: data.difficulty || 'NORMAL'
    }),

    solveProblem: (data) => api.post('/ai/solve', {
      problem: data.problem,
      context: data.context || null
    }),

    // ─── RÉSUMER UN DOCUMENT ──────────────────────────────────────
    summarizeDocument: (formData) => {
      if (!(formData instanceof FormData)) {
        const fd = new FormData();
        fd.append('file', formData);
        formData = fd;
      }
        // ✅ L'intercepteur request gère automatiquement le Content-Type pour FormData
      return api.post('/ai/summarize', formData);
    },

    // ─── CORRIGER UN TRAVAIL ──────────────────────────────────────
    correctWork: (formData) => {
      if (!(formData instanceof FormData)) {
        const fd = new FormData();
        fd.append('file', formData);
        formData = fd;
      }
      // ✅ L'intercepteur request gère automatiquement le Content-Type pour FormData
      return api.post('/ai/correct', formData);
    },

    aiHealth: () => api.get('/ai/health'),
};

