import { useState, useEffect } from 'react';

const REPO = 'LUC-cmd/vitrine';
// Version actuelle de l'app (synchronisée avec versionName dans build.gradle)
const CURRENT_VERSION = '2.1.0';

function parseVersion(tag) {
  return (tag || '').replace(/^v/, '').trim();
}

function isNewer(remote, current) {
  const r = remote.split('.').map(Number);
  const c = current.split('.').map(Number);
  for (let i = 0; i < Math.max(r.length, c.length); i++) {
    const rv = r[i] || 0, cv = c[i] || 0;
    if (rv > cv) return true;
    if (rv < cv) return false;
  }
  return false;
}

export function useAppUpdate() {
  const [updateInfo, setUpdateInfo] = useState(null); // { version, downloadUrl }

  useEffect(() => {
    // Vérifier uniquement dans l'app native Capacitor (pas sur le web)
    const isNative = !!(window.Capacitor?.isNativePlatform?.() || window.Capacitor?.platform);
    if (!isNative) return;

    const check = async () => {
      try {
        const res = await fetch(
          `https://api.github.com/repos/${REPO}/releases/latest`,
          { headers: { Accept: 'application/vnd.github.v3+json' }, signal: AbortSignal.timeout(8000) }
        );
        if (!res.ok) return;
        const data = await res.json();
        const remoteVersion = parseVersion(data.tag_name);

        if (!isNewer(remoteVersion, CURRENT_VERSION)) return;

        // Trouver l'APK Android dans les assets
        const apkAsset = (data.assets || []).find(a =>
          a.name?.toLowerCase().includes('android') && a.name?.endsWith('.apk')
        );
        const downloadUrl = apkAsset?.browser_download_url || data.html_url;

        setUpdateInfo({ version: remoteVersion, downloadUrl });
      } catch {
        // Silencieux — pas de connexion ou GitHub rate-limit
      }
    };

    // Délai de 3s après le démarrage pour ne pas bloquer le splash screen
    const t = setTimeout(check, 3000);
    return () => clearTimeout(t);
  }, []);

  return { updateInfo, dismiss: () => setUpdateInfo(null) };
}

export { CURRENT_VERSION };
