import React from 'react';
import { motion } from 'framer-motion';
import { Download, Sparkles, RefreshCw } from 'lucide-react';
import { CURRENT_VERSION } from '../hooks/useAppUpdate';

const AppUpdateModal = ({ version, downloadUrl, onDismiss }) => {
  const handleDownload = () => {
    if (window.Capacitor?.Plugins?.Browser) {
      window.Capacitor.Plugins.Browser.open({ url: downloadUrl });
    } else {
      window.open(downloadUrl, '_blank');
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      style={{
        position: 'fixed', inset: 0, zIndex: 99999,
        background: 'rgba(2,6,23,0.92)',
        backdropFilter: 'blur(8px)',
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        padding: '24px',
      }}
    >
      <motion.div
        initial={{ scale: 0.88, y: 24, opacity: 0 }}
        animate={{ scale: 1, y: 0, opacity: 1 }}
        transition={{ type: 'spring', damping: 22, stiffness: 300 }}
        style={{
          background: '#07101E',
          border: '1px solid rgba(56,189,248,0.25)',
          borderRadius: 24,
          padding: '32px 28px',
          maxWidth: 380,
          width: '100%',
          boxShadow: '0 32px 80px rgba(0,0,0,0.6)',
          textAlign: 'center',
        }}
      >
        {/* Icône animée */}
        <motion.div
          animate={{ rotate: [0, 15, -15, 0] }}
          transition={{ duration: 1.2, repeat: Infinity, repeatDelay: 2 }}
          style={{
            width: 68, height: 68, borderRadius: '50%',
            background: 'linear-gradient(135deg, #0EA5E9, #8B5CF6)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            margin: '0 auto 20px',
            boxShadow: '0 8px 28px rgba(14,165,233,0.4)',
          }}
        >
          <RefreshCw size={30} color="white" />
        </motion.div>

        {/* Titre */}
        <h2 style={{ color: '#f0f9ff', fontWeight: 900, fontSize: '1.3rem', margin: '0 0 8px' }}>
          Mise à jour disponible
        </h2>

        {/* Versions */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 12, margin: '16px 0' }}>
          <span style={{
            background: 'rgba(239,68,68,0.15)', color: '#F87171',
            padding: '4px 14px', borderRadius: 20,
            fontSize: '0.82rem', fontWeight: 700,
            border: '1px solid rgba(239,68,68,0.25)',
          }}>
            v{CURRENT_VERSION}
          </span>
          <span style={{ color: '#38BDF8', fontSize: '1.1rem', fontWeight: 700 }}>→</span>
          <span style={{
            background: 'rgba(16,185,129,0.15)', color: '#34D399',
            padding: '4px 14px', borderRadius: 20,
            fontSize: '0.82rem', fontWeight: 700,
            border: '1px solid rgba(16,185,129,0.25)',
          }}>
            v{version}
          </span>
        </div>

        {/* Description */}
        <p style={{ color: '#94A3B8', fontSize: '0.88rem', lineHeight: 1.6, margin: '0 0 28px' }}>
          Une nouvelle version de <strong style={{ color: '#7DD3FC' }}>RevisIA H24</strong> est disponible avec des améliorations et corrections.
        </p>

        {/* Bouton principal */}
        <button
          onClick={handleDownload}
          style={{
            width: '100%',
            padding: '15px',
            borderRadius: 14,
            border: 'none',
            background: 'linear-gradient(135deg, #0EA5E9, #8B5CF6)',
            color: 'white',
            fontWeight: 900,
            fontSize: '1rem',
            cursor: 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10,
            boxShadow: '0 6px 20px rgba(14,165,233,0.4)',
            marginBottom: 12,
          }}
        >
          <Download size={20} />
          Télécharger la mise à jour
        </button>

        {/* Bouton secondaire */}
        <button
          onClick={onDismiss}
          style={{
            width: '100%',
            padding: '12px',
            borderRadius: 14,
            border: '1px solid rgba(255,255,255,0.1)',
            background: 'transparent',
            color: '#64748B',
            fontWeight: 700,
            fontSize: '0.88rem',
            cursor: 'pointer',
          }}
        >
          Plus tard
        </button>

        {/* Note */}
        <p style={{ color: '#475569', fontSize: '0.72rem', margin: '16px 0 0', lineHeight: 1.5 }}>
          <Sparkles size={10} style={{ verticalAlign: 'middle', marginRight: 4 }} />
          Installe le fichier .apk téléchargé pour mettre à jour sans perdre tes données.
        </p>
      </motion.div>
    </motion.div>
  );
};

export default AppUpdateModal;
