import React from 'react';
import {
  GraduationCap, BookOpen, PenTool, Atom, Calculator, Lightbulb,
  Microscope, Globe, FlaskConical, Ruler, Brain, Award, Pi, BookMarked
} from 'lucide-react';

/**
 * Fond animé "vidéo" — halos colorés (aurora) + icônes éducatives flottantes.
 * À placer en premier enfant d'un conteneur (position: fixed, derrière le contenu).
 *
 * Props:
 *   variant   : 'blue' | 'green' | 'purple' | 'orange'  (palette)
 *   intensity : 0..1 (opacité globale, défaut 0.5)
 *   icons     : bool — afficher les icônes éducatives flottantes (défaut true)
 */
const PALETTES = {
  blue:   ['#38BDF8', '#3B82F6', '#0EA5E9'],
  green:  ['#10B981', '#0D9488', '#34D399'],
  purple: ['#8B5CF6', '#6366F1', '#A78BFA'],
  orange: ['#F97316', '#FB923C', '#F59E0B'],
};

const EDU_ICONS = [
  GraduationCap, BookOpen, PenTool, Atom, Calculator, Lightbulb,
  Microscope, Globe, FlaskConical, Ruler, Brain, Award, Pi, BookMarked,
];

// Positions/tailles pseudo-aléatoires mais stables (pas de re-render aléatoire)
const FLOATERS = Array.from({ length: 16 }, (_, i) => ({
  Icon: EDU_ICONS[i % EDU_ICONS.length],
  top: (i * 61 + 7) % 92,
  left: (i * 47 + 5) % 94,
  size: 22 + (i % 4) * 12,
  duration: 6 + (i % 5) * 2,
  delay: (i % 6) * 0.7,
  rotate: (i % 2 === 0 ? 1 : -1) * ((i * 13) % 25),
  anim: i % 2 === 0 ? 'ria-float' : 'ria-float-slow',
}));

const AnimatedBackground = ({ variant = 'blue', intensity = 0.5, icons = true }) => {
  const colors = PALETTES[variant] || PALETTES.blue;
  const accent = colors[0];

  const orb = (color, size, top, left, anim, duration, delay = 0) => ({
    position: 'absolute',
    top, left,
    width: size, height: size,
    borderRadius: '50%',
    background: `radial-gradient(circle, ${color}aa 0%, ${color}00 70%)`,
    filter: 'blur(40px)',
    animation: `${anim} ${duration}s ease-in-out ${delay}s infinite`,
    pointerEvents: 'none',
  });

  return (
    <div
      aria-hidden="true"
      style={{
        position: 'fixed',
        inset: 0,
        overflow: 'hidden',
        zIndex: 0,
        opacity: intensity,
        pointerEvents: 'none',
      }}
    >
      {/* Halos aurora */}
      <div style={orb(colors[0], '420px', '-80px', '-60px', 'ria-aurora-1', 16)} />
      <div style={orb(colors[1], '360px', '40%', '60%', 'ria-aurora-2', 20, 1)} />
      <div style={orb(colors[2], '300px', '70%', '10%', 'ria-aurora-3', 18, 2)} />

      {/* Icônes éducatives flottantes */}
      {icons && FLOATERS.map((f, i) => {
        const Icon = f.Icon;
        return (
          <Icon
            key={i}
            size={f.size}
            color={accent}
            style={{
              position: 'absolute',
              top: `${f.top}%`,
              left: `${f.left}%`,
              opacity: 0.10,
              transform: `rotate(${f.rotate}deg)`,
              animation: `${f.anim} ${f.duration}s ease-in-out ${f.delay}s infinite`,
            }}
          />
        );
      })}

      {/* Grain léger pour un rendu "film" */}
      <div style={{
        position: 'absolute', inset: 0,
        backgroundImage: 'radial-gradient(rgba(255,255,255,0.025) 1px, transparent 1px)',
        backgroundSize: '4px 4px',
        opacity: 0.5,
      }} />
    </div>
  );
};

export default AnimatedBackground;
