import React, { useEffect, useState, lazy, Suspense } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { clearSession, getStoredSession } from './utils/authSession';
import { getDashboardPathForRole } from './utils/backHandler';
import { ConfirmProvider } from './components/ConfirmProvider';
import DownloadManager from './components/DownloadManager';
import { wakeBackend, publicAPI } from './services/api';
import { useAppUpdate } from './hooks/useAppUpdate';
import AppUpdateModal from './components/AppUpdateModal';
// Chargés immédiatement — nécessaires au premier rendu
import SplashScreen from './components/SplashScreen';
import LandingPage from './components/LandingPage';
import AuthPage from './AuthPage';
import ActivateAccount from './components/ActivateAccount';
import './styles/responsive.css';
import './App.css';

// Chargés à la demande — réduit le bundle initial de ~70% → premier chargement 2× plus rapide
const StudentDashboard    = lazy(() => import('./components/StudentDashboard'));
const AdminDashboard      = lazy(() => import('./components/AdminDashboard'));
const DelegateDashboard   = lazy(() => import('./components/DelegateDashboard'));
const SuperAdminDashboard = lazy(() => import('./components/SuperAdminDashboard'));
const ParentDashboard     = lazy(() => import('./components/ParentDashboard'));
const CommercialDashboard = lazy(() => import('./components/CommercialDashboard'));
const TeacherDashboard    = lazy(() => import('./components/TeacherDashboard'));
const Messaging           = lazy(() => import('./components/Messaging'));
const Pricing             = lazy(() => import('./components/Pricing'));
const Library             = lazy(() => import('./components/Library'));
const Marketplace         = lazy(() => import('./components/Marketplace'));

// Fallback minimal pendant le lazy-load d'un dashboard
const PageLoader = () => (
  <div style={{
    minHeight: '100dvh', display: 'flex', alignItems: 'center', justifyContent: 'center',
    background: '#F0F9FF',
  }}>
    <div style={{
      width: 42, height: 42, borderRadius: '50%',
      border: '3px solid rgba(56,189,248,0.15)',
      borderTopColor: '#38BDF8',
      animation: 'spin 0.7s linear infinite',
    }} />
    <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
  </div>
);

// Composant de protection des routes
const ProtectedRoute = ({ children, allowedRoles }) => {
  const { token, role } = getStoredSession();
  
  if (!token) {
    return <Navigate to="/auth" replace />;
  }
  
  if (allowedRoles && !allowedRoles.includes(role)) {
    clearSession();
    return <Navigate to="/" replace />;
  }
  
  return children;
};

function App() {
  const [showSplash, setShowSplash] = useState(true);
  // 'waking' | 'ready' | 'offline'
  const [backendStatus, setBackendStatus] = useState('waking');
  const { updateInfo, dismiss } = useAppUpdate();

  // ═══════════════════════════════════════════════════════════════
  // TOUS LES HOOKS DOIVENT ÊTRE APPELÉS AU DÉBUT (avant tout return)
  // ═══════════════════════════════════════════════════════════════

  // ── Réveil du backend dès l'ouverture — Render free tier dort après 15 min ──
  // Lance le ping en arrière-plan pendant le splash screen.
  // Quand prêt → window.__backendReady = true (évite un double réveil dans StudentDashboard)
  useEffect(() => {
    window.__backendReady = false;
    wakeBackend().then(ok => {
      window.__backendReady = !!ok;
      setBackendStatus(ok ? 'ready' : 'offline');
    });
  }, []);

  // ── Keep-alive : ping toutes les 4 min pour empêcher Render de rendormir le backend ──
  // Render free tier endort les services après 15 min d'inactivité.
  // Si le ping échoue → reset window.__backendReady = false (le prochain envoi déclenchera un réveil).
  useEffect(() => {
    const keepAlive = setInterval(async () => {
      try {
        await publicAPI.getStats();
        window.__backendReady = true;
      } catch {
        // Backend rendormi — le flag est remis à false pour forcer un réveil au prochain envoi
        window.__backendReady = false;
      }
    }, 4 * 60 * 1000); // 4 minutes
    return () => clearInterval(keepAlive);
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // Afficher le Splash Screen au démarrage
  useEffect(() => {
    if (showSplash) {
      const timer = setTimeout(() => {
        setShowSplash(false);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [showSplash]);

  // ── Notifications (locales + push Firebase) — actif dans l'APK uniquement ──
  useEffect(() => {
    const isNative = !!(window.Capacitor?.isNativePlatform?.() || window.Capacitor?.platform);
    if (!isNative) return; // navigateur web → rien
    import('./utils/notifications').then(m => {
      m.initNotificationsRevision();
      m.initPushNotifications();
    }).catch(() => {});
  }, []);

  // ── Bouton RETOUR Android (APK) : navigation intelligente dans l'app ──
  useEffect(() => {
    let remove = () => {};
    (async () => {
      try {
        const { runBackHandlers } = await import('./utils/backHandler');
        const { App: CapApp } = await import('@capacitor/app');
        const handle = await CapApp.addListener('backButton', () => {
          if (runBackHandlers()) return;

          const p = window.location.pathname;
          const { role } = getStoredSession();
          const home = getDashboardPathForRole(role);

          // Activation compte → retour vers connexion
          if (p === '/activate') {
            window.location.href = '/auth';
            return;
          }

          // Pages satellites → retour au dashboard du rôle
          if (['/library', '/marketplace', '/messaging', '/pricing'].includes(p)) {
            window.location.href = home;
            return;
          }

          // Dashboards : laisser les handlers internes gérer ; sinon quitter
          const dashboardRoots = ['/', '/auth', '/student', '/admin', '/super-admin',
            '/delegate', '/commercial', '/parent', '/teacher'];
          if (!dashboardRoots.includes(p)) {
            window.history.back();
            return;
          }

          if (p === '/' || p === '/auth') {
            const quitter = window.confirm('Voulez-vous vraiment quitter RevisIA_H24 ?');
            if (quitter) CapApp.exitApp();
            return;
          }

          const quitter = window.confirm('Voulez-vous vraiment quitter RevisIA_H24 ?');
          if (quitter) CapApp.exitApp();
        });
        remove = () => handle.remove();
      } catch (e) {
        // Pas dans l'APK (navigateur web) → rien à faire
      }
    })();
    return () => remove();
  }, []);

  // ═══════════════════════════════════════════════════════════════
  // MAINTENANT on peut utiliser des returns conditionnels
  // ═══════════════════════════════════════════════════════════════

  if (showSplash) {
    return <SplashScreen onComplete={() => setShowSplash(false)} />;
  }

  // Badge discret "⚡ Serveur en démarrage..." — disparaît quand le backend est prêt
  const BackendWakingBadge = backendStatus === 'waking' ? (
    <div style={{
      position: 'fixed',
      bottom: 72,
      left: '50%',
      transform: 'translateX(-50%)',
      zIndex: 99998,
      background: 'white',
      border: '1px solid rgba(99,102,241,0.3)',
      color: '#6366f1',
      borderRadius: 20,
      padding: '5px 14px',
      fontSize: 12,
      fontWeight: 500,
      display: 'flex',
      alignItems: 'center',
      gap: 7,
      backdropFilter: 'blur(12px)',
      WebkitBackdropFilter: 'blur(12px)',
      boxShadow: '0 2px 16px rgba(0,0,0,0.4)',
      pointerEvents: 'none',
      whiteSpace: 'nowrap',
    }}>
      <span style={{
        width: 7, height: 7, borderRadius: '50%',
        background: '#818CF8',
        display: 'inline-block',
        animation: 'pulse 1.4s ease-in-out infinite',
      }} />
      ⚡ Serveur en démarrage…
    </div>
  ) : null;

  return (
    <ConfirmProvider>
      {updateInfo && (
        <AppUpdateModal
          version={updateInfo.version}
          downloadUrl={updateInfo.downloadUrl}
          onDismiss={dismiss}
        />
      )}
      {BackendWakingBadge}
      <DownloadManager />
      <Suspense fallback={<PageLoader />}>
      <Router future={{ v7_startTransition: true, v7_relativeSplatPath: true }}>
        <Routes>
          {/* Routes publiques */}
          <Route path="/" element={<LandingPage />} />
        <Route path="/auth" element={<AuthPage />} />
        <Route path="/activate" element={<ActivateAccount />} />
        <Route path="/pricing" element={<Pricing />} />

        {/* Routes protégées - Étudiant (tous les rôles connectés) */}
        <Route path="/student" element={
          <ProtectedRoute allowedRoles={['ETUDIANT', 'DELEGUE', 'ADMIN', 'SUPER_ADMIN']}>
            <StudentDashboard />
          </ProtectedRoute>
        } />
        <Route path="/messaging" element={
          <ProtectedRoute allowedRoles={['ETUDIANT', 'DELEGUE', 'ADMIN', 'SUPER_ADMIN']}>
            <Messaging />
          </ProtectedRoute>
        } />
        <Route path="/library" element={
          <ProtectedRoute allowedRoles={['ETUDIANT', 'DELEGUE', 'ADMIN', 'SUPER_ADMIN']}>
            <Library />
          </ProtectedRoute>
        } />
        <Route path="/marketplace" element={
          <ProtectedRoute allowedRoles={['ETUDIANT', 'DELEGUE', 'ADMIN', 'SUPER_ADMIN']}>
            <Marketplace />
          </ProtectedRoute>
        } />

        {/* Routes protégées - Délégué */}
        <Route path="/delegate" element={
          <ProtectedRoute allowedRoles={['DELEGUE', 'ADMIN', 'SUPER_ADMIN']}>
            <DelegateDashboard />
          </ProtectedRoute>
        } />

        {/* Routes protégées - Admin */}
        <Route path="/admin" element={
          <ProtectedRoute allowedRoles={['ADMIN', 'SUPER_ADMIN']}>
            <AdminDashboard />
          </ProtectedRoute>
        } />

        {/* Routes protégées - Super Admin */}
        <Route 
          path="/super-admin" 
          element={<ProtectedRoute allowedRoles={['SUPER_ADMIN']}><SuperAdminDashboard /></ProtectedRoute>} 
        />

        <Route 
          path="/parent" 
          element={<ProtectedRoute allowedRoles={['PARENT', 'ADMIN', 'SUPER_ADMIN']}><ParentDashboard /></ProtectedRoute>} 
        />

        <Route
          path="/commercial"
          element={<ProtectedRoute allowedRoles={['COMMERCIAL', 'ADMIN', 'SUPER_ADMIN']}><CommercialDashboard /></ProtectedRoute>}
        />

        <Route
          path="/teacher"
          element={<ProtectedRoute allowedRoles={['ENSEIGNANT', 'ADMIN', 'SUPER_ADMIN']}><TeacherDashboard /></ProtectedRoute>}
        />

          {/* Redirection par défaut (catch-all) vers l'accueil / login */}
          <Route path="*" element={<Navigate to="/" />} />
        </Routes>
      </Router>
      </Suspense>
    </ConfirmProvider>
  );
}

export default App;
