import React, { useState, useEffect } from 'react';
import { Phone, CheckCircle2, AlertCircle } from 'lucide-react';
import '../styles/PhoneInput.css';

const PhoneInput = ({ selectedCountry, value, onChange, onValidationChange }) => {
  const [isValid, setIsValid] = useState(false);

  useEffect(() => {
    if (!selectedCountry) {
      setIsValid(false);
      return;
    }

    const isCorrectLength = String(value).length === selectedCountry.phoneLength;
    setIsValid(isCorrectLength);

    if (onValidationChange) {
      onValidationChange(isCorrectLength);
    }
  }, [value, selectedCountry, onValidationChange]);

  const handleChange = (e) => {
    // Only allow digits (0-9)
    const digitsOnly = e.target.value.replace(/[^\d]/g, '');

    // Limit to country's phone length
    const limited = digitsOnly.slice(0, selectedCountry?.phoneLength || 15);

    onChange(limited);
  };

  if (!selectedCountry) {
    return (
      <div className="phone-input-wrapper disabled">
        <div className="phone-input-header">
          <label>Numéro WhatsApp</label>
          <span className="phone-hint">Sélectionnez d'abord un pays</span>
        </div>
        <div className="phone-input-container">
          <Phone size={18} className="phone-icon" />
          <div className="phone-code-display">+XXX</div>
          <input
            type="text"
            placeholder="Numéro (0 chiffres)"
            disabled
            className="phone-input"
          />
          <div className="phone-counter">0/0</div>
        </div>
      </div>
    );
  }

  const currentLength = String(value).length;
  const requiredLength = selectedCountry.phoneLength;

  return (
    <div className="phone-input-wrapper">
      <div className="phone-input-header">
        <label>Numéro WhatsApp</label>
        <span className="phone-hint">
          {currentLength === 0 ? (
            `${requiredLength} chiffres requis`
          ) : currentLength === requiredLength ? (
            <span className="hint-valid">✓ Numéro valide</span>
          ) : (
            <span className="hint-warning">
              {requiredLength - currentLength} chiffre{requiredLength - currentLength > 1 ? 's' : ''} manquant{requiredLength - currentLength > 1 ? 's' : ''}
            </span>
          )}
        </span>
      </div>

      <div className={`phone-input-container ${isValid ? 'valid' : ''}`}>
        <Phone size={18} className="phone-icon" />
        <div className="phone-code-display">{selectedCountry.phoneCode}</div>
        <input
          type="text"
          placeholder={`Ex: ${generateExample(selectedCountry.phoneLength)}`}
          value={value}
          onChange={handleChange}
          maxLength={selectedCountry.phoneLength}
          className="phone-input"
          inputMode="numeric"
        />
        <div className="phone-counter">
          {currentLength}/{requiredLength}
        </div>

        {isValid && (
          <div className="validation-indicator valid">
            <CheckCircle2 size={20} />
          </div>
        )}
        {currentLength > 0 && !isValid && (
          <div className="validation-indicator invalid">
            <AlertCircle size={20} />
          </div>
        )}
      </div>

      {currentLength > 0 && (
        <div className="phone-preview">
          <span className="preview-label">Format complet :</span>
          <span className="preview-value">
            {selectedCountry.phoneCode} {formatPhoneDisplay(value, selectedCountry.phoneLength)}
          </span>
        </div>
      )}
    </div>
  );
};

// Helper function to generate example numbers based on length
const generateExample = (length) => {
  if (length === 8) return '99099509';
  if (length === 9) return '901234567';
  if (length === 10) return '9012345678';
  return '0'.repeat(length);
};

// Helper function to format phone display with spacing
const formatPhoneDisplay = (value, length) => {
  // Add spacing every 2-3 digits for readability
  if (length === 8) {
    return `${value.slice(0, 4)} ${value.slice(4, 8)}`.trim();
  }
  if (length === 9) {
    return `${value.slice(0, 3)} ${value.slice(3, 6)} ${value.slice(6, 9)}`.trim();
  }
  if (length === 10) {
    return `${value.slice(0, 3)} ${value.slice(3, 6)} ${value.slice(6, 10)}`.trim();
  }
  return value;
};

export default PhoneInput;

