import React, { createContext, useContext, useState, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { AlertTriangle, CheckCircle2, X } from 'lucide-react';

/**
 * Système de confirmation global et réutilisable.
 * Usage : const confirm = useConfirm();
 *   if (await confirm({ titre, message, danger, texteOk })) { … }
 */
const ConfirmContext = createContext(() => Promise.resolve(false));
export const useConfirm = () => useContext(ConfirmContext);

export function ConfirmProvider({ children }) {
  const [dialog, setDialog] = useState(null);

  const confirm = useCallback((opts = {}) => {
    return new Promise((resolve) => {
      setDialog({
        titre: opts.titre || 'Confirmer',
        message: opts.message || 'Êtes-vous sûr ?',
        danger: !!opts.danger,
        texteOk: opts.texteOk || (opts.danger ? 'Supprimer' : 'Confirmer'),
        texteAnnuler: opts.texteAnnuler || 'Annuler',
        resolve,
      });
    });
  }, []);

  const fermer = (val) => { dialog?.resolve(val); setDialog(null); };

  const couleur = dialog?.danger ? '#EF4444' : '#38BDF8';

  return (
    <ConfirmContext.Provider value={confirm}>
      {children}
      <AnimatePresence>
        {dialog && (
          <motion.div
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            style={{ position: 'fixed', inset: 0, background: 'rgba(2,6,23,0.78)', backdropFilter: 'blur(8px)', zIndex: 99999, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16 }}
            onClick={(e) => { if (e.target === e.currentTarget) fermer(false); }}>
            <motion.div
              initial={{ scale: 0.9, y: 20, opacity: 0 }} animate={{ scale: 1, y: 0, opacity: 1 }} exit={{ scale: 0.9, opacity: 0 }}
              transition={{ type: 'spring', stiffness: 420, damping: 30 }}
              style={{ background: 'white', border: `1px solid ${couleur}30`, borderRadius: 24, padding: '28px 26px', maxWidth: 420, width: '100%', textAlign: 'center', boxShadow: '0 16px 48px rgba(0,0,0,0.1)' }}>
              <div style={{ width: 60, height: 60, borderRadius: '50%', background: `${couleur}1a`, border: `2px solid ${couleur}40`, display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 18px' }}>
                {dialog.danger ? <AlertTriangle size={26} color={couleur} /> : <CheckCircle2 size={26} color={couleur} />}
              </div>
              <h3 style={{ color: '#0f172a', fontWeight: 800, fontSize: '1.2rem', margin: '0 0 8px' }}>{dialog.titre}</h3>
              <p style={{ color: '#475569', fontSize: '0.9rem', lineHeight: 1.6, margin: '0 0 24px' }}>{dialog.message}</p>
              <div style={{ display: 'flex', gap: 12 }}>
                <button onClick={() => fermer(false)}
                  style={{ flex: 1, padding: '13px', borderRadius: 14, border: '1px solid #e2e8f0', background: '#f1f5f9', color: '#475569', fontWeight: 700, fontSize: '0.88rem', cursor: 'pointer' }}>
                  {dialog.texteAnnuler}
                </button>
                <button onClick={() => fermer(true)}
                  style={{ flex: 1, padding: '13px', borderRadius: 14, border: 'none', background: dialog.danger ? 'linear-gradient(135deg,#EF4444,#DC2626)' : 'linear-gradient(135deg,#0EA5E9,#0284C7)', color: '#fff', fontWeight: 800, fontSize: '0.88rem', cursor: 'pointer', boxShadow: `0 4px 20px ${couleur}55` }}>
                  {dialog.texteOk}
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </ConfirmContext.Provider>
  );
}
