import { useState, useEffect } from 'react';

/**
 * Hook pour détecter la taille d'écran et adapter le layout
 * Breakpoints:
 * - xs: 0px (téléphone petit)
 * - sm: 640px (téléphone)
 * - md: 768px (tablette)
 * - lg: 1024px (desktop)
 * - xl: 1280px (grand desktop)
 */
export const useResponsive = () => {
  const [screenSize, setScreenSize] = useState({
    width: typeof window !== 'undefined' ? window.innerWidth : 0,
    height: typeof window !== 'undefined' ? window.innerHeight : 0,
    isMobile: typeof window !== 'undefined' && window.innerWidth < 768,
    isTablet: typeof window !== 'undefined' && window.innerWidth >= 768 && window.innerWidth < 1024,
    isDesktop: typeof window !== 'undefined' && window.innerWidth >= 1024,
    isSmallPhone: typeof window !== 'undefined' && window.innerWidth < 375,
    isLargePhone: typeof window !== 'undefined' && window.innerWidth >= 375 && window.innerWidth < 768,
  });

  useEffect(() => {
    const handleResize = () => {
      const width = window.innerWidth;
      const height = window.innerHeight;

      setScreenSize({
        width,
        height,
        isMobile: width < 768,
        isTablet: width >= 768 && width < 1024,
        isDesktop: width >= 1024,
        isSmallPhone: width < 375,
        isLargePhone: width >= 375 && width < 768,
      });
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return screenSize;
};

// Breakpoints constants
export const BREAKPOINTS = {
  xs: 0,
  sm: 640,
  md: 768,
  lg: 1024,
  xl: 1280,
};

// Media queries strings
export const MEDIA_QUERIES = {
  mobile: '(max-width: 767px)',
  tablet: '(min-width: 768px) and (max-width: 1023px)',
  desktop: '(min-width: 1024px)',
  smallPhone: '(max-width: 374px)',
  largePhone: '(min-width: 375px) and (max-width: 767px)',
};
