import React, { useState, useEffect } from 'react';
import { Download, X, CheckCircle, AlertCircle, Pause, Play, Trash2, DownloadCloud } from 'lucide-react';
import { fileDownloadManager } from '../services/fileDownloadManager';
import { useResponsive } from '../hooks/useResponsive';

/**
 * DownloadManager - Affiche et gère les téléchargements
 */
const DownloadManager = () => {
  const [downloads, setDownloads] = useState([]);
  const [showPanel, setShowPanel] = useState(false);
  const { isMobile } = useResponsive();

  useEffect(() => {
    // S'abonner aux changements de téléchargements
    const unsubscribe = fileDownloadManager.subscribe(() => {
      setDownloads([...fileDownloadManager.getAllDownloads()]);
    });

    return unsubscribe;
  }, []);

  const handleClearCompleted = () => {
    downloads
      .filter(d => d.status === 'completed' || d.status === 'error')
      .forEach(d => fileDownloadManager.removeDownload(d.id));
  };

  const handleRemoveDownload = (downloadId) => {
    fileDownloadManager.removeDownload(downloadId);
  };

  const activeCount = downloads.filter(d => d.status === 'downloading').length;
  const completedCount = downloads.filter(d => d.status === 'completed').length;

  if (downloads.length === 0) {
    return null;
  }

  return (
    <div
      style={{
        position: 'fixed',
        bottom: isMobile ? 0 : 20,
        right: isMobile ? 0 : 20,
        left: isMobile ? 0 : 'auto',
        zIndex: 1000,
        width: isMobile ? '100%' : '400px',
        maxHeight: '80vh',
        background: 'white',
        borderRadius: isMobile ? '12px 12px 0 0' : '12px',
        boxShadow: '0 8px 32px rgba(0,0,0,0.15)',
        display: 'flex',
        flexDirection: 'column',
        overflow: 'hidden',
        animation: 'slideUp 0.3s ease'
      }}
    >
      {/* En-tête */}
      <div
        style={{
          padding: '12px 16px',
          background: 'linear-gradient(135deg, #3b82f6 0%, #2563eb 100%)',
          color: 'white',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          cursor: 'pointer'
        }}
        onClick={() => setShowPanel(!showPanel)}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <DownloadCloud size={18} />
          <span style={{ fontWeight: 700 }}>
            Téléchargements ({activeCount}/{downloads.length})
          </span>
        </div>
        <button
          onClick={(e) => {
            e.stopPropagation();
            setShowPanel(!showPanel);
          }}
          style={{
            background: 'rgba(255,255,255,0.2)',
            border: 'none',
            color: 'white',
            width: '32px',
            height: '32px',
            borderRadius: '50%',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center'
          }}
        >
          {showPanel ? '▼' : '▲'}
        </button>
      </div>

      {/* Liste des téléchargements */}
      {showPanel && (
        <div
          style={{
            flex: 1,
            overflowY: 'auto',
            padding: '12px',
            display: 'flex',
            flexDirection: 'column',
            gap: '12px'
          }}
        >
          {downloads.map(download => (
            <DownloadItem
              key={download.id}
              download={download}
              onRemove={handleRemoveDownload}
            />
          ))}

          {/* Bouton effacer complétés */}
          {completedCount > 0 && (
            <button
              onClick={handleClearCompleted}
              style={{
                padding: '8px 12px',
                background: '#f0f0f0',
                border: 'none',
                borderRadius: '6px',
                cursor: 'pointer',
                fontSize: '12px',
                fontWeight: 600,
                color: '#666',
                transition: 'all 0.2s'
              }}
              onMouseEnter={(e) => e.target.style.background = '#e0e0e0'}
              onMouseLeave={(e) => e.target.style.background = '#f0f0f0'}
            >
              Effacer les téléchargements complétés
            </button>
          )}
        </div>
      )}

      <style jsx>{`
        @keyframes slideUp {
          from {
            transform: translateY(100%);
            opacity: 0;
          }
          to {
            transform: translateY(0);
            opacity: 1;
          }
        }
      `}</style>
    </div>
  );
};

/**
 * Composant pour un téléchargement unique
 */
const DownloadItem = ({ download, onRemove }) => {
  const getStatusColor = () => {
    switch (download.status) {
      case 'completed':
        return '#10b981';
      case 'error':
        return '#ef4444';
      case 'downloading':
        return '#3b82f6';
      default:
        return '#64748b';
    }
  };

  const getStatusIcon = () => {
    switch (download.status) {
      case 'completed':
        return <CheckCircle size={16} style={{ color: '#10b981' }} />;
      case 'error':
        return <AlertCircle size={16} style={{ color: '#ef4444' }} />;
      default:
        return <Download size={16} style={{ color: '#3b82f6' }} />;
    }
  };

  return (
    <div
      style={{
        padding: '10px',
        background: '#f8fafc',
        borderRadius: '8px',
        border: `1px solid ${getStatusColor()}33`
      }}
    >
      {/* Nom du fichier */}
      <div style={{ display: 'flex', gap: '8px', alignItems: 'center', marginBottom: '6px' }}>
        {getStatusIcon()}
        <span
          style={{
            flex: 1,
            fontSize: '13px',
            fontWeight: 600,
            color: '#1f2937',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap'
          }}
        >
          {download.filename}
        </span>
      </div>

      {/* Progression et infos */}
      {download.status === 'downloading' && (
        <>
          <div
            style={{
              width: '100%',
              height: '4px',
              background: '#e5e7eb',
              borderRadius: '2px',
              overflow: 'hidden',
              marginBottom: '6px'
            }}
          >
            <div
              style={{
                height: '100%',
                background: `linear-gradient(90deg, #3b82f6 0%, #2563eb 100%)`,
                width: `${download.progress}%`,
                transition: 'width 0.3s ease'
              }}
            />
          </div>

          {/* Stats */}
          <div
            style={{
              display: 'flex',
              justifyContent: 'space-between',
              fontSize: '11px',
              color: '#475569',
              marginBottom: '6px'
            }}
          >
            <span>
              {fileDownloadManager.formatFileSize(download.loaded)} /{' '}
              {fileDownloadManager.formatFileSize(download.total)}
            </span>
            <span>{download.progress.toFixed(0)}%</span>
          </div>

          {/* Vitesse et temps */}
          <div
            style={{
              display: 'flex',
              justifyContent: 'space-between',
              fontSize: '11px',
              color: '#94a3b8'
            }}
          >
            <span>{fileDownloadManager.getSpeed(download.id)}</span>
            <span>{fileDownloadManager.getEstimatedTime(download.id)}</span>
          </div>
        </>
      )}

      {/* Message statut */}
      {download.status === 'completed' && (
        <div style={{ fontSize: '12px', color: '#10b981', fontWeight: 600 }}>
          ✅ Téléchargement complété
        </div>
      )}

      {download.status === 'error' && (
        <div style={{ fontSize: '12px', color: '#ef4444', fontWeight: 600 }}>
          ❌ {download.error}
        </div>
      )}

      {/* Bouton supprimer */}
      <button
        onClick={() => onRemove(download.id)}
        style={{
          width: '100%',
          marginTop: '8px',
          padding: '6px',
          background: 'white',
          border: '1px solid #e5e7eb',
          borderRadius: '6px',
          cursor: 'pointer',
          fontSize: '12px',
          color: '#666',
          fontWeight: 600,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          gap: '6px',
          transition: 'all 0.2s'
        }}
        onMouseEnter={(e) => {
          e.target.style.background = '#fee';
          e.target.style.borderColor = '#fcc';
          e.target.style.color = '#c33';
        }}
        onMouseLeave={(e) => {
          e.target.style.background = 'white';
          e.target.style.borderColor = '#e5e7eb';
          e.target.style.color = '#666';
        }}
      >
        <Trash2 size={12} /> Supprimer
      </button>
    </div>
  );
};

export default DownloadManager;
