// Système de gestion du bouton RETOUR (Android + web).
// Chaque écran peut enregistrer un handler qui "consomme" le retour
// (ferme un modal, revient à l'écran précédent…). Si aucun ne consomme,
// l'app demande à quitter.

const handlers = [];

/** Chemin dashboard selon le rôle connecté */
export function getDashboardPathForRole(role) {
  const map = {
    SUPER_ADMIN: '/super-admin',
    ADMIN: '/admin',
    DELEGUE: '/delegate',
    PARENT: '/parent',
    COMMERCIAL: '/commercial',
    ENSEIGNANT: '/teacher',
    ETUDIANT: '/student',
  };
  return map[role] || '/student';
}

/** Enregistre un handler de retour. Retourne une fonction de désinscription.
 *  Le handler doit retourner true s'il a géré le retour, false sinon. */
export function pushBackHandler(fn) {
  handlers.push(fn);
  return () => {
    const i = handlers.indexOf(fn);
    if (i >= 0) handlers.splice(i, 1);
  };
}

/** Exécute les handlers du plus récent au plus ancien.
 *  S'arrête au premier qui retourne true. Retourne true si géré. */
export function runBackHandlers() {
  for (let i = handlers.length - 1; i >= 0; i--) {
    try {
      if (handlers[i]()) return true;
    } catch (e) { /* ignore */ }
  }
  return false;
}
