/* ── Typewriter hook ─────────────────────────────────────────── */
const useTypewriter = (texts, speed = 60, pause = 2200) => {
  const [display, setDisplay] = useState('');
  const [textIdx, setTextIdx] = useState(0);
  const [charIdx, setCharIdx] = useState(0);
  const [deleting, setDeleting] = useState(false);
  useEffect(() => {
    const current = texts[textIdx];
    const delay = deleting ? speed / 2 : charIdx === current.length ? pause : speed;
    const t = setTimeout(() => {
      if (!deleting && charIdx < current.length) { setDisplay(current.slice(0, charIdx + 1)); setCharIdx(c => c + 1); }
      else if (!deleting && charIdx === current.length) { setDeleting(true); }
      else if (deleting && charIdx > 0) { setDisplay(current.slice(0, charIdx - 1)); setCharIdx(c => c - 1); }
      else { setDeleting(false); setTextIdx(i => (i + 1) % texts.length); }
    }, delay);
    return () => clearTimeout(t);
  }, [charIdx, deleting, textIdx, texts, speed, pause]);
  return display;
};

/* ── Counter hook ────────────────────────────────────────────── */
const useCounter = (target, duration = 1800, start = false) => {
  const [count, setCount] = useState(0);
  useEffect(() => {
    if (!start) return;
    let s = null;
    const step = (ts) => {
      if (!s) s = ts;
      const p = Math.min((ts - s) / duration, 1);
      setCount(Math.floor(p * target));
      if (p < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }, [start, target, duration]);
  return count;
};

/* ── Stat Card ───────────────────────────────────────────────── */
const StatCard = ({ value, suffix = '', label, icon, color, delay = 0 }) => {
  const [inView, setInView] = useState(false);
  const ref = useRef();
  const count = useCounter(value, 1800, inView);
  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => { if (e.isIntersecting) setInView(true); }, { threshold: 0.5 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);
  return (
    <motion.div ref={ref}
      initial={{ opacity: 0, y: 30 }} whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }} transition={{ duration: 0.6, delay }}
      whileHover={{ y: -6, scale: 1.03 }}
      className="lp-stat-card" style={{ '--accent': color }}>
      <div className="lp-stat-icon" style={{ background: `${color}22`, color }}>{icon}</div>
      <div className="lp-stat-number" style={{ color }}>{inView ? count : 0}{suffix}</div>
      <div className="lp-stat-label">{label}</div>
    </motion.div>
  );
};

