/**
 * FileDownloadManager - Gère les téléchargements de fichiers
 * Support multi-format: PDF, Word, Excel, PowerPoint, images, etc.
 */

class FileDownloadManager {
  constructor() {
    this.downloads = new Map(); // Map<id, {status, progress, file}>
    this.listeners = new Set(); // Pour observer les changements
  }

  /**
   * Télécharger un fichier
   */
  async downloadFile(url, filename, fileType) {
    const downloadId = `download_${Date.now()}_${Math.random()}`;

    try {
      // Créer une entrée de suivi
      this.downloads.set(downloadId, {
        id: downloadId,
        filename,
        fileType,
        status: 'downloading',
        progress: 0,
        loaded: 0,
        total: 0,
        startTime: Date.now(),
        error: null
      });
      this.notifyListeners();

      // Utiliser fetch avec support de progression
      const response = await fetch(url);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      // Récupérer la taille totale
      const total = parseInt(response.headers.get('content-length'), 10);
      const reader = response.body.getReader();
      const chunks = [];
      let loaded = 0;

      while (true) {
        const { done, value } = await reader.read();

        if (done) break;

        chunks.push(value);
        loaded += value.length;

        // Mettre à jour la progression
        const progress = total ? (loaded / total) * 100 : 0;
        this.downloads.set(downloadId, {
          ...this.downloads.get(downloadId),
          progress,
          loaded,
          total
        });
        this.notifyListeners();
      }

      // Créer le blob et télécharger
      const blob = new Blob(chunks, { type: this.getContentType(fileType) });
      this.saveFile(blob, filename, downloadId);

      return downloadId;
    } catch (error) {
      this.downloads.set(downloadId, {
        ...this.downloads.get(downloadId),
        status: 'error',
        error: error.message
      });
      this.notifyListeners();
      throw error;
    }
  }

  /**
   * Télécharger et ouvrir un fichier
   */
  async downloadAndOpen(url, filename, fileType) {
    try {
      const downloadId = await this.downloadFile(url, filename, fileType);
      const download = this.downloads.get(downloadId);

      if (download.status === 'completed') {
        // Ouvrir dans une nouvelle fenêtre si possible
        const link = download.downloadUrl;
        window.open(link, '_blank');
      }
    } catch (error) {
      console.error('Erreur téléchargement:', error);
      throw error;
    }
  }

  /**
   * Sauvegarder le fichier
   */
  saveFile(blob, filename, downloadId) {
    // Créer une URL blob
    const blobUrl = URL.createObjectURL(blob);

    // Créer un lien de téléchargement
    const link = document.createElement('a');
    link.href = blobUrl;
    link.download = filename;
    link.style.display = 'none';

    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    // Nettoyer
    setTimeout(() => URL.revokeObjectURL(blobUrl), 100);

    // Mettre à jour le statut
    this.downloads.set(downloadId, {
      ...this.downloads.get(downloadId),
      status: 'completed',
      progress: 100,
      downloadUrl: blobUrl,
      completedTime: Date.now()
    });
    this.notifyListeners();
  }

  /**
   * Obtenir le type MIME
   */
  getContentType(fileType) {
    const mimeTypes = {
      pdf: 'application/pdf',
      docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      doc: 'application/msword',
      xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      xls: 'application/vnd.ms-excel',
      pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
      ppt: 'application/vnd.ms-powerpoint',
      jpg: 'image/jpeg',
      jpeg: 'image/jpeg',
      png: 'image/png',
      gif: 'image/gif',
      txt: 'text/plain',
      csv: 'text/csv',
      zip: 'application/zip'
    };
    return mimeTypes[fileType?.toLowerCase()] || 'application/octet-stream';
  }

  /**
   * Obtenir les informations de téléchargement
   */
  getDownload(downloadId) {
    return this.downloads.get(downloadId);
  }

  /**
   * Obtenir tous les téléchargements
   */
  getAllDownloads() {
    return Array.from(this.downloads.values());
  }

  /**
   * Obtenir les téléchargements en cours
   */
  getActiveDownloads() {
    return Array.from(this.downloads.values()).filter(
      d => d.status === 'downloading'
    );
  }

  /**
   * Supprimer un téléchargement
   */
  removeDownload(downloadId) {
    const download = this.downloads.get(downloadId);
    if (download && download.downloadUrl) {
      URL.revokeObjectURL(download.downloadUrl);
    }
    this.downloads.delete(downloadId);
    this.notifyListeners();
  }

  /**
   * Effacer tous les téléchargements
   */
  clearAll() {
    this.downloads.forEach((download) => {
      if (download.downloadUrl) {
        URL.revokeObjectURL(download.downloadUrl);
      }
    });
    this.downloads.clear();
    this.notifyListeners();
  }

  /**
   * Observer les changements
   */
  subscribe(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  notifyListeners() {
    this.listeners.forEach(listener => listener());
  }

  /**
   * Formater le temps écoulé
   */
  getFormattedTime(downloadId) {
    const download = this.downloads.get(downloadId);
    if (!download) return '';

    const elapsed = Date.now() - download.startTime;
    const seconds = Math.floor(elapsed / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);

    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
    return `${seconds}s`;
  }

  /**
   * Calculer la vitesse de téléchargement
   */
  getSpeed(downloadId) {
    const download = this.downloads.get(downloadId);
    if (!download) return 0;

    const elapsed = (Date.now() - download.startTime) / 1000;
    if (elapsed === 0) return 0;

    const speedBps = download.loaded / elapsed;

    if (speedBps > 1024 * 1024) {
      return (speedBps / (1024 * 1024)).toFixed(2) + ' MB/s';
    } else if (speedBps > 1024) {
      return (speedBps / 1024).toFixed(2) + ' KB/s';
    }
    return speedBps.toFixed(2) + ' B/s';
  }

  /**
   * Calculer le temps restant
   */
  getEstimatedTime(downloadId) {
    const download = this.downloads.get(downloadId);
    if (!download || download.progress === 0) return '';

    const elapsed = (Date.now() - download.startTime) / 1000;
    const estimatedTotal = elapsed / (download.progress / 100);
    const remaining = estimatedTotal - elapsed;

    const minutes = Math.floor(remaining / 60);
    const seconds = Math.floor(remaining % 60);

    if (minutes > 0) return `${minutes}m ${seconds}s`;
    return `${seconds}s`;
  }

  /**
   * Formater la taille du fichier
   */
  static formatFileSize(bytes) {
    if (!bytes) return '0 B';

    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));

    return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + ' ' + sizes[i];
  }
}

// Exporter une instance singleton
export const fileDownloadManager = new FileDownloadManager();
export default fileDownloadManager;
