import { initializeApp } from 'firebase/app';
import { getMessaging, getToken, onMessage } from 'firebase/messaging';

// Configuration Firebase (à remplir avec vos vraies clés)
const firebaseConfig = {
  apiKey: process.env.REACT_APP_FIREBASE_API_KEY || "AIzaSyDqVqKv7tJHu7ZvKvKvKvKvKvKvKvKvKvK",
  authDomain: process.env.REACT_APP_FIREBASE_AUTH_DOMAIN || "ul-smart-campus.firebaseapp.com",
  projectId: process.env.REACT_APP_FIREBASE_PROJECT_ID || "ul-smart-campus",
  storageBucket: process.env.REACT_APP_FIREBASE_STORAGE_BUCKET || "ul-smart-campus.appspot.com",
  messagingSenderId: process.env.REACT_APP_FIREBASE_MESSAGING_SENDER_ID || "123456789",
  appId: process.env.REACT_APP_FIREBASE_APP_ID || "1:123456789:web:abc123"
};

let messaging = null;
let initialized = false;

export const initializeFirebase = async () => {
  if (initialized) return true;

  try {
    // Vérifier si le navigateur supporte les notifications
    if (!('serviceWorker' in navigator) || !('Notification' in window)) {
      console.warn('[Firebase] Notifications non supportées par ce navigateur');
      return false;
    }

    // Enregistrer le Service Worker pour les notifications en arrière-plan
    if ('serviceWorker' in navigator) {
      try {
        await navigator.serviceWorker.register('/firebase-messaging-sw.js');
        console.log('[Firebase] Service Worker enregistré ✅');
      } catch (err) {
        console.warn('[Firebase] Impossible d\'enregistrer le Service Worker:', err.message);
      }
    }

    // Initialiser Firebase
    const app = initializeApp(firebaseConfig);
    messaging = getMessaging(app);
    initialized = true;

    console.log('[Firebase] ✅ Initialisé avec succès');
    return true;
  } catch (error) {
    console.error('[Firebase] Erreur initialisation:', error.message);
    return false;
  }
};

// Collecter le FCM token
export const collectFCMToken = async () => {
  if (!initialized || !messaging) {
    console.warn('[Firebase] Firebase non initialisé');
    return null;
  }

  try {
    // Demander la permission de notification
    const permission = await Notification.requestPermission();
    if (permission !== 'granted') {
      console.warn('[Firebase] Permission notifications refusée');
      return null;
    }

    // Récupérer le token
    const token = await getToken(messaging, {
      vapidKey: process.env.REACT_APP_FIREBASE_VAPID_KEY ||
                "BN7tHq7nJc9Kz3x7Y9qRvWxZ2aAbCdEfGhIjKlMnOpQrStUvWxYzAbCdEfGhIjKl"
    });

    console.log('[Firebase] Token FCM collecté ✅', token.substring(0, 20) + '...');
    return token;
  } catch (error) {
    console.error('[Firebase] Erreur collecte token:', error.message);
    return null;
  }
};

// Écouter les messages push en premier plan
export const setupMessageListener = (callback) => {
  if (!messaging) {
    console.warn('[Firebase] Messaging non initialisé');
    return;
  }

  onMessage(messaging, (payload) => {
    console.log('[Firebase] Message reçu en premier plan:', payload);

    // Appeler le callback
    if (callback) {
      callback({
        titre: payload.notification?.title || 'Notification',
        corps: payload.notification?.body || '',
        data: payload.data || {}
      });
    }

    // Afficher notification locale
    if ('serviceWorkerContainer' in navigator && navigator.serviceWorkerContainer.controller) {
      navigator.serviceWorkerContainer.controller.postMessage({
        type: 'SHOW_NOTIFICATION',
        title: payload.notification?.title,
        options: {
          body: payload.notification?.body,
          icon: '/icon-192x192.png',
          badge: '/badge-72x72.png'
        }
      });
    }
  });
};

// Sauvegarder le token au backend
export const saveFCMTokenToBackend = async (token, phone) => {
  if (!token || !phone) return false;

  try {
    const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8080/api';
    const response = await fetch(`${apiUrl}/utilisateurs/update-fcm-token`, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${localStorage.getItem('token')}`
      },
      body: JSON.stringify({
        fcmToken: token,
        phone: phone
      })
    });

    if (response.ok) {
      console.log('[Firebase] Token sauvegardé au backend ✅');
      localStorage.setItem('fcmToken', token);
      return true;
    } else {
      console.error('[Firebase] Erreur sauvegarde token:', response.status);
      return false;
    }
  } catch (error) {
    console.error('[Firebase] Erreur backend:', error.message);
    return false;
  }
};

// Fonction complète: initialiser + collecter + sauvegarder
export const setupPushNotifications = async (phone) => {
  console.log('[Firebase] Initialisation des notifications push...');

  // 1. Initialiser Firebase
  const initialized = await initializeFirebase();
  if (!initialized) {
    console.warn('[Firebase] Configuration incomplète, notifications désactivées');
    return false;
  }

  // 2. Collecter le token
  const token = await collectFCMToken();
  if (!token) {
    console.warn('[Firebase] Impossible de collecter le token');
    return false;
  }

  // 3. Sauvegarder au backend
  const saved = await saveFCMTokenToBackend(token, phone);
  if (!saved) {
    console.warn('[Firebase] Token non sauvegardé au backend');
    return false;
  }

  // 4. Setup message listener
  setupMessageListener((notif) => {
    console.log('[Firebase] 🔔 Notification reçue:', notif.titre);
  });

  return true;
};

export default {
  initializeFirebase,
  collectFCMToken,
  setupMessageListener,
  saveFCMTokenToBackend,
  setupPushNotifications
};
