// Notifications locales (rappels de révision) via Capacitor.
// Sans effet dans un navigateur normal — actif uniquement dans l'APK.

// ── SÉRIE (streak) façon Duolingo ──────────────────────────────────
// Compte les jours consécutifs où l'étudiant ouvre l'app.
const STREAK_KEY = 'revisia_streak';

/** Met à jour la série à l'ouverture de l'app. Retourne { jours, recordBattu, perdue }. */
export function mettreAJourSerie() {
  const aujourdhui = new Date().toDateString();
  let data;
  try { data = JSON.parse(localStorage.getItem(STREAK_KEY) || '{}'); } catch { data = {}; }

  if (data.dernierJour === aujourdhui) {
    return { jours: data.jours || 1, recordBattu: false, perdue: false };
  }

  const hier = new Date(); hier.setDate(hier.getDate() - 1);
  const etaitHier = data.dernierJour === hier.toDateString();

  let jours, perdue = false;
  if (etaitHier) {
    jours = (data.jours || 0) + 1; // continue la série
  } else if (data.dernierJour) {
    jours = 1; perdue = true;       // série cassée → repart à 1
  } else {
    jours = 1;                       // toute première ouverture
  }

  const record = Math.max(data.record || 0, jours);
  const recordBattu = jours > (data.record || 0) && jours > 1;
  try { localStorage.setItem(STREAK_KEY, JSON.stringify({ dernierJour: aujourdhui, jours, record })); } catch {}
  return { jours, record, recordBattu, perdue };
}

/** Lit la série actuelle sans la modifier. */
export function lireSerie() {
  try {
    const d = JSON.parse(localStorage.getItem(STREAK_KEY) || '{}');
    return { jours: d.jours || 0, record: d.record || 0 };
  } catch { return { jours: 0, record: 0 }; }
}

let _LN = null;
async function getLN() {
  if (_LN) return _LN;
  try {
    const mod = await import('@capacitor/local-notifications');
    _LN = mod.LocalNotifications;
    return _LN;
  } catch {
    return null; // pas dans l'APK
  }
}

/** Demande la permission + programme un rappel quotidien de révision. */
export async function initNotificationsRevision() {
  const LN = await getLN();
  if (!LN) return; // navigateur web → rien

  try {
    const perm = await LN.requestPermissions();
    if (perm.display !== 'granted') return;

    // Évite les doublons : on annule les anciens rappels programmés
    try {
      const pending = await LN.getPending();
      if (pending?.notifications?.length) {
        await LN.cancel({ notifications: pending.notifications.map(n => ({ id: n.id })) });
      }
    } catch {}

    // ── Messages style Duolingo : variés, ludiques, motivants, FOMO ──
    const MATIN = [
      { title: '🌅 Bonjour champion !', body: 'Commence ta journée par 5 minutes de révision. Ton cerveau te dira merci !' },
      { title: '☕ Petit défi du matin', body: 'Un quiz rapide avant les cours ? Ouvre RevisIA_H24 et teste-toi !' },
      { title: '🔥 Garde ta série !', body: 'Ne casse pas ta régularité. Une révision aujourd\'hui = un pas vers la réussite.' },
      { title: '🧠 Réveille ton génie', body: 'Les meilleurs étudiants révisent le matin. Et toi ? 💪' },
    ];
    const MIDI = [
      { title: '⚡ Pause révision ?', body: '10 minutes suffisent pour un quiz IA. Profites-en maintenant !' },
      { title: '🎯 Un défi t\'attend', body: 'Relève un quiz sur ta matière préférée. Montre ce que tu vaux !' },
      { title: '📚 N\'oublie pas RevisIA', body: 'Tes camarades révisent en ce moment. Rejoins-les ! 😏' },
      { title: '🏆 Vise le sommet', body: 'Chaque quiz réussi te rapproche de tes examens. On y va ?' },
    ];
    const SOIR = [
      { title: '🌙 Avant de dormir…', body: 'Une dernière révision ? Ce que tu apprends le soir reste mieux en mémoire !' },
      { title: '🔥 Ta série va se casser !', body: 'Tu n\'as pas encore révisé aujourd\'hui. Vite, un quiz avant minuit !' },
      { title: '💎 Termine en beauté', body: 'Finis ta journée avec un résumé IA. Demain tu seras prêt !' },
      { title: '😱 Tes amis te dépassent', body: 'Pendant que tu hésites, d\'autres révisent. Reprends l\'avantage !' },
    ];

    // Rotation quotidienne déterministe (change chaque jour)
    const jour = new Date().getDate();
    const pick = (arr) => arr[jour % arr.length];

    const schedules = [
      { id: 1001, ...pick(MATIN), hour: 8,  minute: 30 },
      { id: 1002, ...pick(MIDI),  hour: 13, minute: 0 },
      { id: 1003, ...pick(SOIR),  hour: 20, minute: 0 },
    ];

    for (const s of schedules) {
      await LN.schedule({
        notifications: [{
          id: s.id,
          title: s.title,
          body: s.body,
          schedule: { on: { hour: s.hour, minute: s.minute }, repeats: true },
        }],
      });
    }
  } catch (e) {
    // silencieux — ne jamais bloquer l'app pour une notif
  }
}

/** Enregistre le téléphone pour les notifications PUSH (Firebase) et envoie le token au backend. */
export async function initPushNotifications() {
  let Push;
  try {
    const mod = await import('@capacitor/push-notifications');
    Push = mod.PushNotifications;
  } catch {
    return; // navigateur web → pas de push
  }

  try {
    const perm = await Push.requestPermissions();
    if (perm.receive !== 'granted') return;

    await Push.register();

    // Token FCM reçu → on l'envoie au backend pour pouvoir notifier cet appareil
    Push.addListener('registration', async (token) => {
      // Stocker localement pour retry après login
      try { localStorage.setItem('fcmToken_pending', token.value); } catch {}
      await _envoyerTokenAuBackend(token.value);
    });

    Push.addListener('registrationError', () => { /* silencieux */ });

    // Notification reçue quand l'app est AU PREMIER PLAN → afficher en local
    Push.addListener('pushNotificationReceived', async (notification) => {
      const LN = await getLN();
      if (!LN) return;
      try {
        await LN.schedule({
          notifications: [{
            id: Math.floor(Math.random() * 90000) + 10000,
            title: notification.title || 'RevisIA',
            body: notification.body || '',
            smallIcon: 'ic_launcher',
          }],
        });
      } catch {}
    });

    // Tap sur une notification (app en arrière-plan ou fermée) → ouvrir l'app
    Push.addListener('pushNotificationActionPerformed', (action) => {
      // L'app s'ouvre automatiquement, on peut naviguer si besoin
      try {
        const data = action.notification?.data || {};
        if (data.url) window.location.href = data.url;
      } catch {}
    });

  } catch (e) { /* silencieux */ }
}

/** Envoie le token FCM au backend. Appelé après login aussi (quand JWT est disponible). */
export async function _envoyerTokenAuBackend(token) {
  if (!token) {
    const stored = localStorage.getItem('fcmToken_pending');
    if (!stored) return;
    token = stored;
  }
  try {
    const jwt = localStorage.getItem('token');
    if (!jwt) return; // pas encore connecté → sera réessayé après login
    const { default: axios } = await import('axios');
    const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8080/api';
    await axios.post(`${apiUrl}/utilisateurs/fcm-token`, { token }, {
      headers: { Authorization: `Bearer ${jwt}` }
    });
    localStorage.removeItem('fcmToken_pending');
  } catch { /* silencieux */ }
}

/** Envoie une notification immédiate (ex: nouveau cours publié). */
export async function notifierMaintenant(title, body) {
  const LN = await getLN();
  if (!LN) return;
  try {
    await LN.schedule({
      notifications: [{ id: Math.floor(Math.random() * 100000), title, body }],
    });
  } catch {}
}
