import React, { useEffect, useState } from 'react';
import { motion } from 'framer-motion';
import '../styles/splash.css';

/**
 * Splash Screen avec Logo REVISIA-H24
 * Affiche au démarrage avec animation
 */
const SplashScreen = ({ onComplete }) => {
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Simuler le chargement (vérifier auth, etc.)
    const timer = setTimeout(() => {
      setIsLoading(false);
      onComplete?.();
    }, 3000); // 3 secondes

    return () => clearTimeout(timer);
  }, [onComplete]);

  return (
    <motion.div
      className="splash-container"
      initial={{ opacity: 1 }}
      animate={{ opacity: isLoading ? 1 : 0 }}
      transition={{ duration: 0.5, delay: isLoading ? 0 : 2.5 }}
      style={{ pointerEvents: isLoading ? 'auto' : 'none' }}
    >
      {/* Background gradient */}
      <div className="splash-background">
        <div className="splash-gradient"></div>
      </div>

      {/* Contenu principal */}
      <div className="splash-content">
        {/* Logo REVISIA-H24 */}
        <motion.div
          className="splash-logo-container"
          initial={{ scale: 0.8, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          transition={{ duration: 0.8, delay: 0.2, type: 'spring' }}
        >
          {/* Cercle animé avec points */}
          <svg
            className="splash-circle"
            viewBox="0 0 120 120"
            width="120"
            height="120"
          >
            <motion.circle
              cx="60"
              cy="60"
              r="50"
              fill="none"
              stroke="#1D4ED8"
              strokeWidth="3"
              initial={{ pathLength: 0 }}
              animate={{ pathLength: 1 }}
              transition={{ duration: 1.5, delay: 0.3 }}
            />
            {/* Points animés */}
            <motion.circle
              cx="60"
              cy="10"
              r="5"
              fill="#F97316"
              animate={{ r: [5, 7, 5] }}
              transition={{ duration: 1.5, repeat: Infinity }}
            />
            <motion.circle
              cx="110"
              cy="60"
              r="5"
              fill="#F97316"
              animate={{ r: [5, 7, 5] }}
              transition={{ duration: 1.5, repeat: Infinity, delay: 0.3 }}
            />
            <motion.circle
              cx="60"
              cy="110"
              r="5"
              fill="#F97316"
              animate={{ r: [5, 7, 5] }}
              transition={{ duration: 1.5, repeat: Infinity, delay: 0.6 }}
            />
            <motion.circle
              cx="10"
              cy="60"
              r="5"
              fill="#F97316"
              animate={{ r: [5, 7, 5] }}
              transition={{ duration: 1.5, repeat: Infinity, delay: 0.9 }}
            />
          </svg>
        </motion.div>

        {/* Texte REVISIA-H24 */}
        <motion.div
          className="splash-text"
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, delay: 1 }}
        >
          <h1>REVISIA</h1>
          <span className="splash-h24">H24</span>
        </motion.div>

        {/* Tagline */}
        <motion.p
          className="splash-tagline"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.8, delay: 1.3 }}
        >
          Plateforme Académique Intelligente
        </motion.p>
      </div>

      {/* Loading Indicator */}
      <motion.div
        className="splash-loader"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.8, delay: 1.5 }}
      >
        <div className="loader-ring">
          <div></div>
          <div></div>
          <div></div>
        </div>
        <p>Chargement...</p>
      </motion.div>

      {/* Version */}
      <div className="splash-version">v1.0.0</div>
    </motion.div>
  );
};

export default SplashScreen;
